function executeSkill(context) {
  const sourcePiece = context.piece;
  const targetAlly = selectTarget({ type: 'piece', range: 10, filter: 'ally' });
  if (!targetAlly || targetAlly.needsTargetSelection) {
    return targetAlly;
  }
  targetAlly.attack += 2;
  const damageResult = dealDamage(sourcePiece, targetAlly, 4, 'true', context.battle, context.skill.id);
  return {
    message: sourcePiece.name + '使用邪能赐福，使' + targetAlly.name + '攻击力+2并受到' + damageResult.damage + '点真实伤害',
    success: true
  };
}

